import React, { useState } from 'react';
import { useSelector } from 'react-redux';
import { RootState } from '../store/store';
import NewsItem from './NewsItem';
import { Form } from 'react-bootstrap';

const NewsList: React.FC = () => {
  const { articles, status, author, category, date } = useSelector((state: RootState) => state);
  const [authorFilter, setAuthorFilter] = useState(author || '');

  if (status === 'loading') return <p>Loading...</p>;
  if (status === 'failed') return <p>Failed to load news.</p>;

  const filteredArticles = articles.filter(article => {
    const articleAuthor = article.author ? article.author.toString().trim().toLowerCase() : '';
    const matchesAuthor = author === '' || articleAuthor.includes(author.trim().toLowerCase());
    const matchesCategory = category === '' || (article.category && article.category.toLowerCase() === category.toLowerCase());
    const matchesDate = date === '' || (article.publishedAt && article.publishedAt.startsWith(date));
    return matchesAuthor && matchesCategory && matchesDate;
  });

  return (
      <Container>
      <Row>
      {filteredArticles.length > 0 ? (
        filteredArticles.map((article, index) => <NewsItem key={index} article={article} />)
      ) : (
        <p>No articles found for the selected filters.</p>
      )}
    </Row>
    </Container>
  );
};

export default NewsList;
